#define PI 3.14159
#define TAU 6.28318

// SDFs provided by Inigo Quilez https://iquilezles.org/articles/distfunctions/
float sdCappedCone( vec3 p, float h, float r1, float r2 )
{
    vec2 q = vec2( length(p.xz), p.y );
    vec2 k1 = vec2(r2,h);
    vec2 k2 = vec2(r2-r1,2.0*h);
    vec2 ca = vec2(q.x-min(q.x,(q.y<0.0)?r1:r2), abs(q.y)-h);
    vec2 cb = q - k1 + k2*clamp( dot(k1-q,k2)/dot(k2, k2), 0.0, 1.0 );
    float s = (cb.x<0.0 && ca.y<0.0) ? -1.0 : 1.0;
    return s*sqrt( min(dot(ca, ca),dot(cb, cb)) );
}
mat2 rot2D(float angle) {
    float c = cos(angle);
    float s = sin(angle);

    return mat2(c, -s, s, c);
}
float cup(vec3 pos) {
    pos -= 2.;
    float d = sdCappedCone(pos, 1., .6, .8);
    pos.y -= 1.;
    d = min(d, sdCappedCone(pos, .2, .83, .86));
    pos.y -= .4;
    d = min(d, sdCappedCone(pos, .2, .83, .86));
    d = max(d, -sdCappedCone(pos, 2.15, .5, 1.));
    return d;
}



void mainImage( out vec4 o, in vec2 U )
{
    vec2 uv = (U *2. - iResolution.xy) / iResolution.y;
    float t = iTime;
    vec3 origin = vec3(0., 0.5, -18.0);
    vec3 ray = normalize(vec3(uv, 3.0));
    origin.xz *= rot2D(-.6 + t*.1);
    ray.xz *= rot2D(-.6 + t*.1);
    ray.zy *= rot2D(0.1 );
    vec3 pos = origin;
    vec3 ti = pos;
    int i = 0;
    float td = 0.;
    vec3 diff = vec3(.9);
    for (i; i < 256; i++) {
        float dist = min(cup(mod(pos, 4.)), cup(mod(pos, 4.) +vec3(0., 4., 0.)));
        td += dist;
        pos = pos+normalize(ray+vec3(cos(t*0.2+pos.x*0.1)*0.03, 0.02*(-td*0.04), sin(t*.443)*0.02)*td)*dist;
        ti = floor(pos*.25);
        if (dist <= 0.001) { diff += texture(iChannel0, pos.xy).rgb*.1; break; }
    }
    o = vec4(mix(diff, vec3(0.5, 0.1, 0.5), min(float(i)*0.01, 1.)),1.0);
}
